from typing import Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadPortNumber

from .snmp import SnmpPdu


class ICT(SnmpPdu):
    """Class provides attributes and private methods to manage a PDU of type APC"""

    def __init__(
            self,
            host: str,
            timeout: Union[float, int] = 10,
            community: str = "write"
    ) -> None:
        super().__init__(host, timeout, community=community)
        self._version = 1
        self._key = "1.3.6.1.4.1.39145.10.8.1.5"

    @property
    def _port_setting(self):
        return {DeviceStatus.ON: "1", DeviceStatus.OFF: "2"}

    def _get_oid_value(self, value):
        return rfc1902.Integer(self._port_setting[value])

    def _build_snmp_oid(self, port):
        if port in range(1, 13):
            return f"{self._key}.{port - 1}"
        else:
            raise BadPortNumber(f"Port number is invalid: {port}")
